WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/15.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/15.0/apex.js")} 
var currencycode = sforce.connection.query("select id,DefaultCurrencyIsoCode from User where id='{!$User.Id}'"); 
//alert(currencycode.records.DefaultCurrencyIsoCode); 
if(currencycode.records.DefaultCurrencyIsoCode== 'EUR'){ 
parent.location.href ='/00O34000005etjm?pv0={!SUBSTITUTE(Account.Country_Parent_ID__c, "'", "\'")}&pv1={!SUBSTITUTE(Account.Country_Parent_Formula__c, "'", "\'")}';
}else{ 
parent.location.href ='/00O340000064qcO?pv0={!SUBSTITUTE(Account.Country_Parent_ID__c, "'", "\'")}&pv1={!SUBSTITUTE(Account.Country_Parent_Formula__c, "'", "\'")}';

}
